-- Migration 434: intake XJZ client-recovered monster skill probe targets.
-- Function: monster battle skill evidence worklist. This does not promote runtime monster skills
-- because the client evidence identifies which monsters must be probed, not skill ids/probability.

CREATE TABLE IF NOT EXISTS god2_research.xjz_monster_skill_probe_targets (
  probe_id BIGINT NOT NULL COMMENT 'XJZ 怪物技能抓包目標 ID',
  monster_code INT NOT NULL COMMENT '客戶端怪物代碼',
  monster_name_zh_tw VARCHAR(150) NOT NULL COMMENT '怪物名稱（繁體中文）',
  field_rom_path VARCHAR(255) NULL COMMENT '場景怪物 ROM 路徑',
  battle_rom_path VARCHAR(255) NULL COMMENT '戰鬥怪物 ROM 路徑',
  actor_skill_kind VARCHAR(64) NOT NULL COMMENT '技能施放者類型',
  wanted_fields_zh_tw VARCHAR(255) NOT NULL COMMENT '需要補證的欄位',
  capture_target_table VARCHAR(100) NOT NULL COMMENT '建議抓包回填表',
  source_file VARCHAR(500) NOT NULL COMMENT '證據來源檔案',
  source_line INT NULL COMMENT '證據來源行號',
  evidence_status_zh_tw VARCHAR(100) NOT NULL COMMENT '目前證據狀態',
  needs_packet_evidence TINYINT(1) NOT NULL COMMENT '是否仍需要封包或黑箱證據',
  formal_monster_id BIGINT NULL COMMENT '正式服務端怪物 ID',
  formal_monster_name_zh_tw VARCHAR(150) NULL COMMENT '正式服務端怪物名稱',
  formal_link_status_zh_tw VARCHAR(80) NOT NULL DEFAULT '待連結' COMMENT '正式怪物連結狀態',
  created_at_utc DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6) COMMENT '建立 UTC 時間',
  PRIMARY KEY (probe_id),
  UNIQUE KEY ux_xjz_monster_skill_probe_monster_code (monster_code),
  KEY ix_xjz_monster_skill_probe_formal_monster (formal_monster_id),
  KEY ix_xjz_monster_skill_probe_needed (needs_packet_evidence),
  CONSTRAINT ck_xjz_monster_skill_probe_needs_packet CHECK (needs_packet_evidence IN (0,1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='XJZ 客戶端還原怪物技能抓包目標';

TRUNCATE TABLE god2_research.xjz_monster_skill_probe_targets;

