UPDATE god2_research.xjz_monster_skill_probe_targets target
JOIN god2_game.monsters monster
  ON monster.code = CONCAT('monster_', target.monster_code)
SET target.formal_monster_id = monster.monster_id,
    target.formal_monster_name_zh_tw = monster.name_zh_tw,
    target.formal_link_status_zh_tw = '已連結正式怪物';

UPDATE god2_research.xjz_monster_skill_probe_targets
SET formal_link_status_zh_tw = '正式怪物未建立'
WHERE formal_monster_id IS NULL;

CREATE OR REPLACE VIEW god2_research.vw_xjz_monster_skill_probe_targets_readable AS
SELECT
  probe_id,
  monster_code,
  COALESCE(formal_monster_name_zh_tw, monster_name_zh_tw) AS monster_name_zh_tw,
  field_rom_path,
  battle_rom_path,
  '怪物戰鬥技能' AS game_function_zh_tw,
  wanted_fields_zh_tw,
  CASE needs_packet_evidence WHEN 1 THEN '需要抓包或黑箱測試' ELSE '已可套用' END AS evidence_need_zh_tw,
  evidence_status_zh_tw,
  formal_monster_id,
  formal_link_status_zh_tw,
  source_file,
  source_line
FROM god2_research.xjz_monster_skill_probe_targets;

INSERT INTO god2_research.static_gap_remediation_queue
  (legacy_table_name, formal_table_name, priority_rank, remediation_category_zh_tw,
   game_function_zh_tw, evidence_policy_zh_tw, remediation_action_zh_tw,
   dependency_check_zh_tw, current_status_zh_tw, safe_to_apply_automatically,
   safe_to_drop_legacy_now, reviewed_at_utc)
VALUES
  ('xjz_monster_skill_probe_targets', 'monster_skills', 40, '補證清單',
   '怪物戰鬥技能',
   '客戶端還原只能證明需補測的怪物身份，不能直接證明技能 ID、觸發條件或使用機率。',
   '使用 xjz_monster_skill_probe_targets 對 215 隻怪物補抓技能欄位、技能效果、使用機率與觸發條件；證據來源為 XJZ C# 客戶端還原 monster_skill_probe_template；未確認前不啟用正式 monster_skills。',
   '已確認正式 monster_skills 需要 monster_id 與 skill_id 外鍵；目前只建立補證清單，不寫入正式技能表。',
   '已建立怪物技能抓包目標，正式技能仍待證據',
   0, 0, UTC_TIMESTAMP())
ON DUPLICATE KEY UPDATE
  priority_rank = VALUES(priority_rank),
  remediation_category_zh_tw = VALUES(remediation_category_zh_tw),
  game_function_zh_tw = VALUES(game_function_zh_tw),
  evidence_policy_zh_tw = VALUES(evidence_policy_zh_tw),
  remediation_action_zh_tw = VALUES(remediation_action_zh_tw),
  dependency_check_zh_tw = VALUES(dependency_check_zh_tw),
  current_status_zh_tw = VALUES(current_status_zh_tw),
  safe_to_apply_automatically = VALUES(safe_to_apply_automatically),
  safe_to_drop_legacy_now = VALUES(safe_to_drop_legacy_now),
  reviewed_at_utc = VALUES(reviewed_at_utc);

UPDATE god2_research.formal_table_server_correspondence
SET server_correspondence_status_zh_tw = '服務端表存在；已補抓包目標，正式資料待技能證據',
    runtime_usage_policy_zh_tw = 'monster_skills 只有在技能 ID、觸發條件與機率有證據或服主設計規則後才能啟用。',
    cleanup_decision_zh_tw = '保留正式空表；用 xjz_monster_skill_probe_targets 作為補證清單。',
    reviewed_at_utc = UTC_TIMESTAMP(6)
WHERE schema_name = 'god2_game' AND table_name = 'monster_skills';
